for guide, versions in GUIDES.items():
    for lang, text in versions.items():
        source = SOURCE / (guide + "-" + lang + ".txt")
        source.write_text(text, encoding="utf-8")
        voice = "kn" if lang == "kn" else "en"
        wav = OUT / (guide + "-" + lang + ".wav")
        mp3 = OUT / (guide + "-" + lang + ".mp3")
        subprocess.run(["espeak-ng", "-v", voice, "-s", "150", "-a", "100", "-f", str(source), "-w", str(wav)], check=True)
        subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-i", str(wav), "-codec:a", "libmp3lame", "-b:a", "64k", str(mp3)], check=True)
        wav.unlink()
        print(guide + "-" + lang, mp3.stat().st_size)

